# 031 - un bottone abbassa la voce del brano scaricato, lasciando i cori.
#
# Il lavoro lo fa un modello sul PROCESSORE: nessuna scheda video, e dopo la
# prima volta niente internet. Misurato: circa un terzo della durata del brano
# (194 s di musica in 56 s).
#
# ⚠️ Nel programma compilato manca sia il motore (onnxruntime) sia il modello:
#    si scaricano DA SOLI al primo uso, come gia' succede per yt-dlp e deno.
#    Chi non preme il bottone non scarica niente.
#
# SE NON VA BENE: `patch_031 = 0` la spegne su una macchina sola.

MODULO = '# -*- coding: utf-8 -*-\n"""\ndevocalizza.py — toglie (o abbassa) la voce da un brano, sul PC del cliente.\n\nCOME FUNZIONA\n    Usa un modello MDX-Net, lo stesso che sta dentro Ultimate Vocal Remover.\n    Lavora sullo spettro: il suono viene scomposto in 3072 bande, il modello\n    dice quali parti sono musica, e quello che resta e\' la voce.\n\n    Il modello gira con onnxruntime SUL PROCESSORE: non serve una scheda\n    video, e nemmeno la connessione dopo la prima volta.\n\nCOSA SERVE, E COME SE LO PROCURA\n    - onnxruntime  (~14 MB, da PyPI)   in dipendenze/devocalizza/\n    - il modello   (~64 MB, da GitHub) in dipendenze/devocalizza/\n    Si scaricano DA SOLI al primo uso, come gia\' succede per yt-dlp e deno:\n    il cliente non deve installare niente a mano. Chi non preme il bottone\n    non scarica nulla.\n\n⚠️ NON TOGLIE LA VOCE PERFETTAMENTE, e non e\' un difetto: e\' un modello\n   veloce, scelto per girare su qualunque PC. Lasciando dentro un po\' di voce\n   originale (`quanto_voce`) i difetti si sentono molto meno - ed e\' anche\n   quello che serve dal vivo, dove la voce guida aiuta chi canta.\n"""\n\nimport os\nimport subprocess\nimport sys\nimport threading\nimport urllib.request\n\n# --- DUE MODI, e cambiano il risultato per chi canta:\n#\n#     "tutta"  toglie TUTTA la voce, cori compresi.\n#     "cori"   toglie SOLO chi canta davanti e LASCIA I CORI nella base —\n#              e i cori nella base sono un miglioramento gia\' misurato su 14\n#              brani in questo progetto, non un\'opinione.\n#\n# ⚠️ I due modelli NON hanno le stesse misure: il primo lavora su 3072 bande,\n#    il secondo su 2048, e la finestra da cui vengono e\' diversa. Sbagliarla\n#    non da\' errore: il modello risponde lo stesso e separa male. Il valore\n#    del secondo (5120) e\' stato TROVATO PROVANDO, non copiato.\nMODELLI = {\n    \'tutta\': dict(file="UVR-MDX-NET-Inst_HQ_3.onnx",\n                  n_fft=6144, dim_f=3072, dim_t=256, hop=1024),\n    \'cori\':  dict(file="UVR_MDXNET_KARA_2.onnx",\n                  n_fft=5120, dim_f=2048, dim_t=256, hop=1024),\n}\n# ⭐ Si parte da \'cori\': chi canta davanti sparisce, i cori restano nella\n#    base. E\' quello che serve dal vivo — e i cori nella base sono un\n#    miglioramento gia\' misurato su 14 brani in questo progetto.\nPREDEFINITO = \'cori\'\nBASE_URL = ("https://github.com/TRvlvr/model_repo/releases/download/"\n            "all_public_uvr_models/")\n\nSR = 44100\n\n# ⛔ Le misure si prendono TUTTE dallo stesso modo, mai una per una a mano:\n#    scriverle a mano significa, prima o poi, avere il nome di un modello e la\n#    finestra di un altro. E quell\'errore non si vede — il modello risponde\n#    lo stesso e separa male.\n_M = MODELLI[PREDEFINITO]\nN_FFT = _M[\'n_fft\']\nHOP = _M[\'hop\']\nDIM_F = _M[\'dim_f\']\nDIM_T = _M[\'dim_t\']\nCHUNK = HOP * (DIM_T - 1)\nMODELLO_NOME = _M[\'file\']\nMODELLO_URL = BASE_URL + MODELLO_NOME\n\n\ndef _usa(modo):\n    """Imposta le misure del modo scelto. Da chiamare PRIMA di separare."""\n    global N_FFT, HOP, DIM_F, DIM_T, CHUNK, MODELLO_NOME, MODELLO_URL\n    m = MODELLI.get(modo or PREDEFINITO) or MODELLI[PREDEFINITO]\n    N_FFT, HOP, DIM_F, DIM_T = m[\'n_fft\'], m[\'hop\'], m[\'dim_f\'], m[\'dim_t\']\n    CHUNK = HOP * (DIM_T - 1)\n    if MODELLO_NOME != m[\'file\']:\n        _sessione[0] = None            # cambia modello: si riapre\n    MODELLO_NOME = m[\'file\']\n    MODELLO_URL = BASE_URL + MODELLO_NOME\n    return m\n# la ruota di onnxruntime per la versione di Python con cui e\' fatto il\n# programma: deve combaciare, altrimenti non si carica\nONNX_URL = ("https://files.pythonhosted.org/packages/source-independent/"\n            "onnxruntime-1.29.0-cp313-cp313-win_amd64.whl")\nONNX_PYPI = "https://pypi.org/pypi/onnxruntime/json"\n\n_lucchetto = threading.Lock()\n_sessione = [None]\n\n\n# --------------------------------------------------------------- le cartelle\ndef _base():\n    """La cartella del programma, sia da sorgente sia compilato."""\n    if getattr(sys, \'frozen\', False) or (\'__compiled__\' in globals()):\n        return os.path.dirname(os.path.abspath(sys.argv[0]))\n    return os.path.abspath(os.path.join(os.path.dirname(__file__), \'..\'))\n\n\ndef cartella():\n    d = os.path.join(_base(), \'dipendenze\', \'devocalizza\')\n    try:\n        os.makedirs(d, exist_ok=True)\n    except Exception:\n        # in Program Files potrebbe non essere scrivibile: si ripiega\n        # nella cartella dell\'utente, dove i permessi ci sono sempre\n        d = os.path.join(os.environ.get(\'LOCALAPPDATA\') or\n                         os.path.expanduser(\'~\'), \'KaraDom\', \'devocalizza\')\n        os.makedirs(d, exist_ok=True)\n    return d\n\n\ndef _ffmpeg():\n    for c in (os.path.join(_base(), \'dipendenze\', \'ffmpeg.exe\'),\n              os.path.join(_base(), \'ffmpeg.exe\'),\n              \'ffmpeg\'):\n        if c == \'ffmpeg\' or os.path.exists(c):\n            return c\n    return \'ffmpeg\'\n\n\n# ------------------------------------------------------- procurarsi il pezzo\ndef _scarica(url, dove, avviso=None):\n    """Scarica dicendo a che punto e\', e NON lascia mai un file a meta\':\n    si scrive in un file temporaneo e si rinomina solo alla fine."""\n    tmp = dove + \'.parte\'\n    req = urllib.request.Request(url, headers={\'User-Agent\': \'KaraDom\'})\n    with urllib.request.urlopen(req, timeout=60) as r:\n        totale = int(r.headers.get(\'Content-Length\') or 0)\n        fatto = 0\n        with open(tmp, \'wb\') as f:\n            while True:\n                pezzo = r.read(262144)\n                if not pezzo:\n                    break\n                f.write(pezzo)\n                fatto += len(pezzo)\n                if avviso and totale:\n                    avviso(fatto * 100 // totale)\n    os.replace(tmp, dove)\n    return dove\n\n\ndef _onnx_wheel_url():\n    """L\'indirizzo vero della ruota giusta, chiesto a PyPI.\n\n    Non si scrive a mano: gli indirizzi dei pacchetti cambiano a ogni\n    versione, e uno sbagliato darebbe un 404 al primo cliente che prova.\n    """\n    import json\n    tag = \'cp%d%d\' % (sys.version_info[0], sys.version_info[1])\n    with urllib.request.urlopen(ONNX_PYPI, timeout=30) as r:\n        dati = json.loads(r.read().decode(\'utf-8\'))\n    for versione in sorted(dati.get(\'releases\', {}), reverse=True):\n        for file in dati[\'releases\'][versione]:\n            n = file.get(\'filename\', \'\')\n            if tag in n and \'win_amd64\' in n and n.endswith(\'.whl\'):\n                return file[\'url\'], n\n    raise RuntimeError("nessuna versione di onnxruntime per Python %s"\n                       % \'.\'.join(map(str, sys.version_info[:2])))\n\n\ndef procura_onnxruntime(avviso=None):\n    """Ritorna il modulo onnxruntime, scaricandolo se non c\'e\'."""\n    try:\n        import onnxruntime\n        return onnxruntime\n    except Exception:\n        pass\n\n    d = cartella()\n    if d not in sys.path:\n        sys.path.insert(0, d)\n    try:\n        import onnxruntime\n        return onnxruntime\n    except Exception:\n        pass\n\n    if avviso:\n        avviso(0, "Scarico il motore (una volta sola, ~14 MB)…")\n    url, nome = _onnx_wheel_url()\n    whl = os.path.join(d, nome)\n    if not os.path.exists(whl):\n        _scarica(url, whl, (lambda p: avviso(p, "Motore… %d%%" % p)) if avviso else None)\n    # la ruota e\' uno zip: si scompatta qui dentro e basta\n    import zipfile\n    with zipfile.ZipFile(whl) as z:\n        z.extractall(d)\n    try:\n        os.remove(whl)\n    except Exception:\n        pass\n    import onnxruntime\n    return onnxruntime\n\n\ndef procura_modello(avviso=None):\n    d = cartella()\n    f = os.path.join(d, MODELLO_NOME)\n    if not os.path.exists(f):\n        if avviso:\n            avviso(0, "Scarico il modello (una volta sola, ~64 MB)…")\n        _scarica(MODELLO_URL, f,\n                 (lambda p: avviso(p, "Modello… %d%%" % p)) if avviso else None)\n    return f\n\n\ndef pronto():\n    """True se non c\'e\' niente da scaricare."""\n    try:\n        import onnxruntime  # noqa: F401\n        motore = True\n    except Exception:\n        motore = os.path.isdir(os.path.join(cartella(), \'onnxruntime\'))\n    return motore and os.path.exists(os.path.join(cartella(), MODELLO_NOME))\n\n\n# --------------------------------------------------------------- lo spettro\ndef _finestra():\n    import numpy as np\n    # hann periodica, la stessa che usa il modello in addestramento\n    n = np.arange(N_FFT)\n    return (0.5 - 0.5 * np.cos(2.0 * np.pi * n / N_FFT)).astype(\'float32\')\n\n\ndef _stft(x, win):\n    """x: (canali, campioni) -> (canali, DIM_F, frame) complesso.\n\n    Bordi riflessi, come `center=True`: senza, il primo e l\'ultimo pezzo di\n    ogni blocco perderebbero energia e si sentirebbero gli attacchi.\n    """\n    import numpy as np\n    meta = N_FFT // 2\n    x = np.pad(x, ((0, 0), (meta, meta)), mode=\'reflect\')\n    frame = 1 + (x.shape[1] - N_FFT) // HOP\n    fuori = np.empty((x.shape[0], DIM_F, frame), dtype=\'complex64\')\n    for i in range(frame):\n        pezzo = x[:, i * HOP:i * HOP + N_FFT] * win\n        fuori[:, :, i] = np.fft.rfft(pezzo, axis=1)[:, :DIM_F]\n    return fuori\n\n\ndef _istft(S, win, campioni):\n    """L\'inverso: si risomma con la finestra e si divide per quanto ogni\n    campione e\' stato coperto, se no dove le finestre si accavallano il\n    suono verrebbe piu\' forte."""\n    import numpy as np\n    canali, _, frame = S.shape\n    meta = N_FFT // 2\n    lungo = (frame - 1) * HOP + N_FFT\n    fuori = np.zeros((canali, lungo), dtype=\'float32\')\n    pesi = np.zeros(lungo, dtype=\'float32\')\n    pieno = np.zeros((canali, N_FFT // 2 + 1), dtype=\'complex64\')\n    for i in range(frame):\n        pieno[:] = 0\n        pieno[:, :DIM_F] = S[:, :, i]\n        onda = np.fft.irfft(pieno, n=N_FFT, axis=1).astype(\'float32\')\n        fuori[:, i * HOP:i * HOP + N_FFT] += onda * win\n        pesi[i * HOP:i * HOP + N_FFT] += win * win\n    pesi[pesi < 1e-8] = 1e-8\n    fuori /= pesi\n    return fuori[:, meta:meta + campioni]\n\n\n# ------------------------------------------------------------- il lavoro vero\ndef _leggi_audio(percorso):\n    """Audio in stereo 44100 tramite ffmpeg: cosi\' legge tutto — mp3, mp4,\n    mkv, quello che c\'e\' — senza altre librerie."""\n    import numpy as np\n    cmd = [_ffmpeg(), \'-v\', \'error\', \'-i\', percorso,\n           \'-f\', \'f32le\', \'-acodec\', \'pcm_f32le\',\n           \'-ac\', \'2\', \'-ar\', str(SR), \'-\']\n    kw = {}\n    if os.name == \'nt\':\n        kw[\'creationflags\'] = 0x08000000      # niente finestra nera\n    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kw)\n    if p.returncode != 0 or not p.stdout:\n        raise RuntimeError("ffmpeg non ha letto l\'audio: %s"\n                           % p.stderr.decode(\'utf-8\', \'replace\')[-300:])\n    d = np.frombuffer(p.stdout, dtype=\'float32\').reshape(-1, 2).T.copy()\n    return d\n\n\ndef _scrivi_audio(dati, percorso):\n    import numpy as np\n    grezzo = np.ascontiguousarray(dati.T.astype(\'float32\')).tobytes()\n    cmd = [_ffmpeg(), \'-v\', \'error\', \'-y\',\n           \'-f\', \'f32le\', \'-ar\', str(SR), \'-ac\', \'2\', \'-i\', \'-\']\n    if percorso.lower().endswith(\'.mp3\'):\n        cmd += [\'-codec:a\', \'libmp3lame\', \'-b:a\', \'320k\']\n    cmd += [percorso]\n    kw = {}\n    if os.name == \'nt\':\n        kw[\'creationflags\'] = 0x08000000\n    p = subprocess.run(cmd, input=grezzo, stdout=subprocess.PIPE,\n                       stderr=subprocess.PIPE, **kw)\n    if p.returncode != 0:\n        raise RuntimeError("ffmpeg non ha scritto il file: %s"\n                           % p.stderr.decode(\'utf-8\', \'replace\')[-300:])\n    return percorso\n\n\ndef quanti_thread(rimisura=False):\n    """Quanti core usare, MISURATO su questa macchina.\n\n    ⛔ Non si indovina: su 16 core usarli tutti e\' risultato il caso PEGGIORE\n       (2,06 s a blocco contro 1,67 con dodici, +19% di attesa) — oltre una\n       certa soglia i thread si ostacolano fra loro. Ma dove sia quella\n       soglia dipende dalla macchina, e una regola fissa andrebbe bene solo\n       sul computer su cui l\'ho scritta.\n\n    Quindi la prima volta si prova davvero: tre impostazioni, un blocco\n    ciascuna, si tiene la piu\' rapida e si ricorda. Costa pochi secondi, una\n    volta sola nella vita del programma.\n    """\n    n = max(1, os.cpu_count() or 4)\n    if not rimisura:\n        try:\n            from .database import Database\n            v = int(str(Database.get_config(\'devoc_thread\', \'0\')).strip())\n            if 1 <= v <= n:\n                return v\n        except Exception:\n            pass\n    # ripiego finche\' la misura non c\'e\': tre quarti dei core\n    return max(2, int(n * 0.75)) if n > 2 else n\n\n\ndef misura_thread(avviso=None):\n    """Prova le impostazioni su UN blocco e ricorda la migliore."""\n    import time\n    import numpy as np\n    import onnxruntime as ort\n\n    n = max(1, os.cpu_count() or 4)\n    candidati = sorted({max(2, n // 2), max(2, int(n * 0.75)), n} if n > 2 else {n})\n    modello = procura_modello(avviso)\n\n    # un blocco di rumore basta: si misura la macchina, non la musica\n    finto = np.random.randn(1, 4, DIM_F, DIM_T).astype(\'float32\') * 0.01\n    esiti = []\n    for th in candidati:\n        try:\n            o = ort.SessionOptions()\n            o.intra_op_num_threads = th\n            o.graph_optimization_level = ort.GraphOptimizationLevel.ORT_ENABLE_ALL\n            s = ort.InferenceSession(modello, sess_options=o,\n                                     providers=[\'CPUExecutionProvider\'])\n            nome = s.get_inputs()[0].name\n            s.run(None, {nome: finto})          # il primo giro scalda\n            t0 = time.perf_counter()\n            s.run(None, {nome: finto})\n            esiti.append((time.perf_counter() - t0, th))\n            del s\n        except Exception:\n            continue\n    if not esiti:\n        return quanti_thread()\n    esiti.sort()\n    migliore = esiti[0][1]\n    try:\n        from .database import Database\n        Database.set_config(\'devoc_thread\', str(migliore))\n    except Exception:\n        pass\n    print("[devocalizza] misurato su questa macchina: %d core su %d "\n          "(%s)" % (migliore, n,\n                    ", ".join("%d=%.2fs" % (t2, t1) for t1, t2 in esiti)))\n    return migliore\n\n\ndef _sessione_onnx(avviso=None):\n    with _lucchetto:\n        if _sessione[0] is not None:\n            return _sessione[0]\n        ort = procura_onnxruntime(avviso)\n        modello = procura_modello(avviso)\n        # la prima volta si misura la macchina, poi il valore resta\n        try:\n            from .database import Database\n            if not str(Database.get_config(\'devoc_thread\', \'\')).strip():\n                if avviso:\n                    avviso(0, "Guardo quanto e\' veloce questo computer…")\n                misura_thread(avviso)\n        except Exception:\n            pass\n        opz = ort.SessionOptions()\n        opz.intra_op_num_threads = quanti_thread()\n        opz.graph_optimization_level = ort.GraphOptimizationLevel.ORT_ENABLE_ALL\n        _sessione[0] = ort.InferenceSession(\n            modello, sess_options=opz, providers=[\'CPUExecutionProvider\'])\n        return _sessione[0]\n\n\ndef separa(percorso, avanzamento=None, modo=None):\n    """(base, voce) come due array (2, campioni). E\' il passo lento."""\n    import numpy as np\n\n    _usa(modo)                       # prima le misure, poi il modello\n    sess = _sessione_onnx(avanzamento)\n    nome_in = sess.get_inputs()[0].name\n    win = _finestra()\n    mix = _leggi_audio(percorso)\n    totale = mix.shape[1]\n\n    base = np.zeros_like(mix)\n    quanti = max(1, (totale + CHUNK - 1) // CHUNK)\n    for n in range(quanti):\n        a = n * CHUNK\n        b = min(totale, a + CHUNK)\n        pezzo = mix[:, a:b]\n        if pezzo.shape[1] < CHUNK:            # l\'ultimo si allunga con silenzio\n            pezzo = np.pad(pezzo, ((0, 0), (0, CHUNK - pezzo.shape[1])))\n        S = _stft(pezzo, win)[:, :, :DIM_T]\n        # ⚠️ L\'ORDINE DEI QUATTRO PIANI CONTA: il modello li vuole alternati\n        #    per canale — sinistro reale, sinistro immaginario, destro reale,\n        #    destro immaginario. Mettendoli a blocchi (prima i due reali, poi\n        #    i due immaginari) il modello non riconosce piu\' niente e\n        #    restituisce quasi l\'ingresso: misurato, toglieva 0,6 dB invece\n        #    di separare.\n        x = np.stack([S[0].real, S[0].imag, S[1].real, S[1].imag],\n                     axis=0).astype(\'float32\')[None]\n        y = sess.run(None, {nome_in: x})[0][0]\n        S2 = np.stack([y[0] + 1j * y[1], y[2] + 1j * y[3]]).astype(\'complex64\')\n        onda = _istft(S2, win, CHUNK)\n        base[:, a:b] = onda[:, :b - a]\n        if avanzamento:\n            avanzamento(int((n + 1) * 100 / quanti), "Separazione… %d%%"\n                        % int((n + 1) * 100 / quanti))\n\n    voce = mix - base\n    return base, voce\n\n\ndef separa_progressiva(percorso, quanto_voce=0.0, modo=None):\n    """Consegna il brano A PEZZI, appena sono pronti.\n\n    Serve per suonare mentre si separa: ogni giro restituisce\n    (secondo_di_inizio, audio_gia_devocalizzato). Il calcolo va a circa meta\'\n    della durata del brano, quindi ogni secondo speso ne produce due: con un\n    piccolo vantaggio iniziale il calcolo resta davanti a chi ascolta per\n    tutto il brano.\n\n    ⚠️ Il primo pezzo costa piu\' degli altri: la prima chiamata al modello\n    include l\'apertura del file e la preparazione, ed e\' il ritardo che\n    l\'ascoltatore sente prima di partire.\n    """\n    import numpy as np\n\n    _usa(modo)                       # prima le misure, poi il modello\n    sess = _sessione_onnx()\n    nome_in = sess.get_inputs()[0].name\n    win = _finestra()\n    mix = _leggi_audio(percorso)\n    totale = mix.shape[1]\n\n    for n in range((totale + CHUNK - 1) // CHUNK):\n        a = n * CHUNK\n        b = min(totale, a + CHUNK)\n        pezzo = mix[:, a:b]\n        vero = pezzo.shape[1]\n        if vero < CHUNK:\n            pezzo = np.pad(pezzo, ((0, 0), (0, CHUNK - vero)))\n        S = _stft(pezzo, win)[:, :, :DIM_T]\n        x = np.stack([S[0].real, S[0].imag, S[1].real, S[1].imag],\n                     axis=0).astype(\'float32\')[None]\n        y = sess.run(None, {nome_in: x})[0][0]\n        S2 = np.stack([y[0] + 1j * y[1], y[2] + 1j * y[3]]).astype(\'complex64\')\n        base = _istft(S2, win, CHUNK)[:, :vero]\n        if quanto_voce > 0:\n            base = base + (mix[:, a:b] - base) * float(quanto_voce)\n        yield a / float(SR), base\n\n\ndef modo_scelto():\n    """Quale dei due modi ha scelto l\'utente nelle Opzioni (scheda Audio)."""\n    try:\n        from .database import Database\n        m = str(Database.get_config(\'devoc_modo\', PREDEFINITO)).strip()\n        if m in MODELLI:\n            return m\n    except Exception:\n        pass\n    return PREDEFINITO\n\n\ndef devocalizza(percorso, uscita=None, quanto_voce=0.0, avanzamento=None,\n                modo=None):\n    """Scrive un file con la voce tolta (o abbassata).\n\n    quanto_voce: 0.0 = via del tutto, 0.3 = ne resta un po\' (suona meglio,\n    perche\' copre i difetti del modello), 1.0 = come l\'originale.\n    modo: se non lo si dice, si usa quello scelto nelle Opzioni.\n    """\n    base, voce = separa(percorso, avanzamento, modo=modo or modo_scelto())\n    if quanto_voce > 0:\n        base = base + voce * float(quanto_voce)\n    # niente distorsione se la somma supera il fondo scala\n    import numpy as np\n    picco = float(np.max(np.abs(base))) if base.size else 0.0\n    if picco > 1.0:\n        base = base / picco\n    if not uscita:\n        radice, est = os.path.splitext(percorso)\n        uscita = radice + \' (devocalizzato)\' + (\'.mp3\' if est.lower() in\n                                                (\'.mp4\', \'.mkv\', \'.webm\', \'.avi\')\n                                                else est)\n    return _scrivi_audio(base, uscita)\n'

CODICE = 'def _leggi_filtro_karaoke(self):\n    """Acceso, se non e\' stato spento apposta. La scelta si ricorda: chi\n    cerca gli originali non deve rispegnerlo a ogni avvio."""\n    try:\n        from .database import Database\n        return str(Database.get_config(\'yt_filtro_karaoke\', \'1\')).strip() not in (\'0\', \'no\', \'off\')\n    except Exception:\n        return True\n\n\ndef _aggiorna_btn_karaoke(self):\n    """Acceso = verde. Spento = grigio e barrato, cosi\' si capisce a colpo\n    d\'occhio che quella parola NON viene aggiunta."""\n    b = getattr(self, \'btn_karaoke\', None)\n    if b is None:\n        return\n    # ⚠️ NON si usa `BTN`: quello e\' una variabile locale di __init__ e qui\n    #    dentro non esiste. Il font si richiede a F, che e\' importata dal\n    #    modulo e tiene conto del ridimensionamento dello schermo.\n    #\n    # Il testo dice cosa succede PREMENDOLO, non com\'e\' adesso: e\' l\'unico\n    # modo perche\' si capisca senza doverci pensare.\n    try:\n        if self._filtro_karaoke:\n            b.config(text=_("togli filtro\\nkaraoke"),\n                     bg=\'#28a745\', fg=\'white\', font=F(\'Segoe UI\', 9, \'bold\'))\n        else:\n            b.config(text=_("rimetti filtro\\nkaraoke"),\n                     bg=\'#495057\', fg=\'#ffd700\', font=F(\'Segoe UI\', 9, \'bold\'))\n    except Exception:\n        pass\n\n# ---------------- togliere la voce ----------------\n\n\ndef _cambia_filtro_karaoke(self):\n    self._filtro_karaoke = not self._filtro_karaoke\n    self._aggiorna_btn_karaoke()\n    try:\n        from .database import Database\n        Database.set_config(\'yt_filtro_karaoke\', \'1\' if self._filtro_karaoke else \'0\')\n    except Exception:\n        pass\n\n\ndef _indirizzo_audio(self, link):\n    """L\'indirizzo diretto dell\'audio di un link YouTube.\n\n    Serve perche\' ffmpeg il link della pagina non lo sa aprire: vuole\n    l\'indirizzo del flusso, quello che yt-dlp ricava con `-g`.\n    """\n    # ⛔ NON si richiama yt-dlp a mano con una combinazione fissa: e\' quello\n    #    che avevo fatto, e falliva ("non sono riuscito a prendere\n    #    l\'audio"). Il programma ha gia\' `_run_ytdlp`, che prova in fila\n    #    piu\' impostazioni contro i blocchi di YouTube — misurate su piu\'\n    #    video, non scelte a caso. Si passa da li\'.\n    from . import youtube_local as yl\n    for formato in (\'bestaudio[ext=m4a]/bestaudio\', \'bestaudio\', _YT_FORMAT_DL):\n        try:\n            out = yl._run_ytdlp([\'--no-warnings\', \'--no-playlist\',\n                                 \'--skip-download\', \'-f\', formato,\n                                 \'--print\', \'%(url)s\', link], timeout=60)\n            if out:\n                for r in out.splitlines():\n                    r = r.strip()\n                    if r.startswith(\'http\'):\n                        return r\n        except Exception as e:\n            print("[devocalizza] formato %s: %s" % (formato, e))\n\n    # ultimo tentativo: l\'indirizzo che il programma usa per riprodurlo\n    try:\n        u, _t = yl.risolvi_url(link)\n        if u and str(u).startswith(\'http\'):\n            return u\n    except Exception as e:\n        print("[devocalizza] risolvi_url: %s" % e)\n    return None\n\n\ndef _on_devocalizza(self):\n    """Sceglie un brano e ne toglie la voce. Il lavoro va in un thread:\n    la finestra deve restare viva, ci vuole circa meta\' della durata."""\n    from tkinter import filedialog, messagebox\n    cartella = (self.cartella_var.get() or \'\').strip()\n\n    # ⭐ DUE SITUAZIONI, non una in coda all\'altra: o si sta lavorando sul\n    #    CAMPO DI RICERCA (un link o un brano appena cercato), oppure c\'e\'\n    #    un BRANO SELEZIONATO nella libreria. Nella pratica ne capita una\n    #    sola per volta; se per caso ci fossero tutte e due, vince quello\n    #    scritto nel campo, perche\' e\' l\'ultima cosa che hai toccato.\n    f = \'\'\n    testo = \'\'\n\n    # QUALUNQUE campo, non solo il mio: prima quello su cui si sta\n    # scrivendo in questo momento, poi il filtro\\brano della libreria (che\n    # e\' quello da cui si parte quasi sempre), poi il campo di ricerca qui.\n    def _leggi(w):\n        try:\n            v = (w.get() or \'\').strip()\n        except Exception:\n            return \'\'\n        if not v or v == self.PH_SEARCH:\n            return \'\'\n        # i campi vuoti mostrano una scritta d\'invito: non e\' un brano\n        for invito in (\'digita per cercare\', \'filtra brano\', \'cerca karaoke\'):\n            if v.lower().startswith(invito):\n                return \'\'\n        return v\n\n    candidati = []\n    try:\n        attivo = self.root.focus_get()\n        if attivo is not None and hasattr(attivo, \'get\'):\n            candidati.append(attivo)\n    except Exception:\n        pass\n    # ⚠️ `_lbl_brano` NON e\' un campo: e\' l\'etichetta "Brano (filtro):".\n    #    Il campo dove si scrive e\' `entry_filtro`.\n    lib = getattr(self.system, \'libreria\', None)\n    w = getattr(lib, \'entry_filtro\', None) if lib else None\n    if w is not None and hasattr(w, \'get\'):\n        candidati.append(w)\n    candidati.append(getattr(self, \'entry_search\', None))\n\n    for w in candidati:\n        if w is None:\n            continue\n        testo = _leggi(w)\n        if testo:\n            break\n\n    if testo:\n        if _is_url(testo):\n            f = testo                      # link: lo si risolve fra poco\n        elif os.path.exists(testo):\n            f = testo                      # e\' un percorso vero\n        else:\n            # un titolo cercato: si prende il file gia\' scaricato che gli\n            # corrisponde, se c\'e\'\n            try:\n                cart = cartella if os.path.isdir(cartella) else None\n                if cart:\n                    f = self._cerca_per_titolo(cart, testo) or \'\'\n            except Exception:\n                f = \'\'\n\n    if not f:\n        try:\n            lib = getattr(self.system, \'libreria\', None)\n            sel = getattr(lib, \'brano_selezionato_path\', None) if lib else None\n            if sel and os.path.exists(sel):\n                f = sel\n        except Exception:\n            pass\n\n    # ⛔ NIENTE finestra per scegliere il file: il brano si prende dal\n    #    campo di ricerca o da quello selezionato, e basta. Se non c\'e\'\n    #    ne\' l\'uno ne\' l\'altro si dice e si smette — chi preme il bottone\n    #    ha gia\' in mente su cosa lavorare, non vuole cercarlo di nuovo.\n    if not f:\n        messagebox.showinfo(\n            _("Su quale brano?"),\n            _("Scrivi un brano o incolla un link nel campo di ricerca, "\n              "oppure seleziona un brano nella libreria."),\n            parent=self.root)\n        return\n\n    finestra = tk.Toplevel(self.root)\n    finestra.title(_("Abbasso la voce"))\n    finestra.configure(bg=\'#141414\')\n    finestra.resizable(False, False)\n    finestra.transient(self.root)\n    lbl = tk.Label(finestra, bg=\'#141414\', fg=\'white\', font=F(\'Segoe UI\', 11),\n                   text=_("Preparo…"), width=46, anchor=\'w\')\n    lbl.pack(padx=S(16), pady=(S(14), S(6)))\n    barra = ttk.Progressbar(finestra, length=S(380), mode=\'determinate\', maximum=100)\n    barra.pack(padx=S(16), pady=(0, S(14)))\n    nota = tk.Label(finestra, bg=\'#141414\', fg=\'#888\', font=F(\'Segoe UI\', 9),\n                    text=_("La prima volta scarica il necessario (~78 MB)."))\n    nota.pack(padx=S(16), pady=(0, S(12)))\n\n    def mostra(percento, testo=\'\'):\n        def agisci():\n            try:\n                if testo:\n                    lbl.config(text=testo)\n                barra[\'value\'] = max(0, min(100, int(percento)))\n            except Exception:\n                pass\n        try:\n            self.root.after(0, agisci)\n        except Exception:\n            pass\n\n    def lavora():\n        try:\n            from . import devocalizza as DV\n            sorgente = f\n            nome_uscita = None\n\n            # ⭐ Se e\' un link, prima serve l\'indirizzo diretto dell\'audio:\n            #    quello ffmpeg lo legge, il link di YouTube no.\n            if _is_url(sorgente):\n                mostra(0, _("Cerco il brano…"))\n                diretto = self._indirizzo_audio(sorgente)\n                if not diretto:\n                    raise RuntimeError(_("Non sono riuscito a prendere "\n                                         "l\'audio da quel link."))\n                # il file finito prende il nome del video, non quello\n                # illeggibile dell\'indirizzo\n                try:\n                    from .youtube_local import titolo_video\n                    t = titolo_video(sorgente) or \'\'\n                except Exception:\n                    t = \'\'\n                t = re.sub(r\'[\\\\/:*?"<>|]\', \'\', t).strip() or \'brano\'\n                dove = cartella if os.path.isdir(cartella) else os.path.dirname(diretto)\n                nome_uscita = os.path.join(dove, t + \' (senza voce).mp3\')\n                sorgente = diretto\n\n            modo = DV.modo_scelto()          # dalle Opzioni, scheda Audio\n            uscita = DV.devocalizza(sorgente, uscita=nome_uscita,\n                                    quanto_voce=0.0, avanzamento=mostra,\n                                    modo=modo)\n            detto = (_("cori lasciati") if modo == \'cori\'\n                     else _("via anche i cori"))\n            def fine():\n                try:\n                    finestra.destroy()\n                except Exception:\n                    pass\n                messagebox.showinfo(\n                    _("Fatto"),\n                    _("Voce abbassata (%s):\\n\\n%s") % (detto, uscita),\n                    parent=self.root)\n            self.root.after(0, fine)\n        except Exception as e:\n            msg = str(e)\n            def male():\n                try:\n                    finestra.destroy()\n                except Exception:\n                    pass\n                messagebox.showerror(_("Non ci sono riuscito"), msg, parent=self.root)\n            self.root.after(0, male)\n\n    threading.Thread(target=lavora, daemon=True, name="Devocalizza").start()\n\n\ndef _largh_btn_karaoke(self):\n    """Quanto e\' largo il tasto del filtro con la scritta piu\' lunga.\n\n    Si misura senza toccare quella che si vede: si mette da parte il testo\n    attuale, si provano tutte e due le scritte, e si rimette com\'era.\n    """\n    b = getattr(self, \'btn_karaoke\', None)\n    if b is None:\n        return 0\n    try:\n        adesso = b.cget(\'text\')\n        largo = 0\n        for t in (_("togli filtro\\nkaraoke"), _("rimetti filtro\\nkaraoke")):\n            b.config(text=t)\n            b.update_idletasks()\n            largo = max(largo, b.winfo_reqwidth())\n        b.config(text=adesso)\n        return largo\n    except Exception:\n        return 0\n\n\ndef _layout_top(self):\n    top = getattr(self, \'_top\', None)\n    if top is None or not top.winfo_exists():\n        return\n    # ⛔ QUI SI CREANO TUTTI E DUE I BOTTONI, non solo il mio.\n    #    Questa funzione ne POSIZIONA due: quello del filtro karaoke (che\n    #    nasce nella 030) e Devocalizza. Ma le patch si sostituiscono a\n    #    vicenda: quando questa subentra alla 030, la sua versione non gira\n    #    piu\' e quel bottone resta inesistente -> \'NoneType\' has no attribute\n    #    \'place\', con la finestra degli errori in faccia all\'utente.\n    #    Una patch non puo\' dare per scontato che un\'altra abbia gia\' fatto\n    #    la sua parte: si controlla e si rimedia.\n    if getattr(self, \'btn_karaoke\', None) is None:\n        self._filtro_karaoke = self._leggi_filtro_karaoke()\n        self.btn_karaoke = tk.Button(top, text=_("togli filtro karaoke"),\n                                     command=self._cambia_filtro_karaoke,\n                                     relief=\'flat\', cursor=\'hand2\',\n                                     bd=0, highlightthickness=0)\n        self._aggiorna_btn_karaoke()\n    if getattr(self, \'btn_devoc\', None) is None:\n        self.btn_devoc = tk.Button(top, text=_("Devocalizza"),\n                                   command=self._on_devocalizza,\n                                   bg=\'#8e44ad\', fg=\'white\',\n                                   relief=\'flat\', cursor=\'hand2\')\n        try:\n            from .libreria_widgets import add_tooltip as _tt031\n            _tt031(self.btn_devoc,\n                   _("Abbassa la voce dell\'ultimo brano scaricato, "\n                     "lasciando i cori. Ci vuole circa un terzo della "\n                     "durata del brano; la prima volta scarica il "\n                     "necessario (~67 MB)."))\n        except Exception:\n            pass\n    try:\n        top.update_idletasks()\n    except Exception:\n        pass\n    W = top.winfo_width()\n    H = top.winfo_height()\n    if W < 40 or H < 10:\n        return\n    ox = top.winfo_rootx()\n\n    def rel(w):\n        try:\n            if w is None:\n                return None\n            wd = w.winfo_width()\n            if wd < 5:\n                return None\n            return (w.winfo_rootx() - ox, wd)\n        except Exception:\n            return None\n\n    lib = getattr(self.system, \'libreria\', None)\n    cant = rel(getattr(lib, \'entry_cantante\', None))\n    brano = rel(getattr(lib, \'_lbl_brano\', None))\n    filt = rel(getattr(lib, \'entry_filtro\', None))\n    pad = S(4)\n\n    # --- Dest: label allineata a "Cant:", campo allineato/largo come cantante ---\n    if cant:\n        xcant, wcant = cant\n    else:\n        xcant, wcant = S(60), (W // 2) - S(90)\n    # X della label "Cant:" = inizio del frame cantante + padx(5)\n    lbl_x = S(5)\n    try:\n        fc = self.system.libreria.entry_cantante.master\n        lbl_x = (fc.winfo_rootx() - ox) + S(5)\n    except Exception:\n        pass\n    self.lbl_dest.place(x=max(0, lbl_x), y=0, height=H)\n    self.entry_dest.place(x=xcant, y=0, width=wcant, height=H)\n\n    # --- Sfoglia sotto i tasti ▶ 🗑 (tra campo cantante e label brano) ---\n    gap_x0 = xcant + wcant + pad\n    gap_x1 = (brano[0] if brano else (filt[0] if filt else W)) - pad\n    sfw = max(S(70), gap_x1 - gap_x0)\n    self.btn_sfoglia.place(x=gap_x0, y=0, width=sfw, height=H)\n\n    # --- campo ricerca: dalla label "Brano (filtro):" a fine campo filtro ---\n    if brano:\n        xsearch = brano[0]\n    elif filt:\n        xsearch = filt[0]\n    else:\n        xsearch = gap_x0 + sfw + pad\n    filtro_right = (filt[0] + filt[1]) if filt else W\n\n    # --- 3 bottoni (Cerca/Download/Incolla) TUTTI larghi uguali (al piu\' largo) ---\n    # ⚠️ La larghezza si prende sul testo PIU\' LUNGO che ciascun bottone\n    #    puo\' mostrare, non su quello di adesso: il tasto del filtro\n    #    cambia scritta quando lo si preme, e se la misura seguisse il\n    #    testo corrente la barra si riassesterebbe a ogni clic.\n    bw = max(self.btn_cerca.winfo_reqwidth(),\n             self.btn_download.winfo_reqwidth(),\n             self.btn_incolla.winfo_reqwidth(),\n             self.btn_devoc.winfo_reqwidth(),\n             self._largh_btn_karaoke()) + S(4)   # appena un filo d\'aria\n    buttons_w = 4 * bw + 4 * pad     # Cerca, Download, Incolla, Devocalizza\n    search_right = min(filtro_right, W - buttons_w - pad)\n    search_right = max(search_right, xsearch + S(80))\n\n    # ⭐ L\'interruttore "karaoke" sta IN FONDO al campo, dentro il suo\n    #    spazio: il campo si accorcia di quel tanto. Cosi\' si vede mentre\n    #    si scrive, senza rubare posto ai tre bottoni.\n    campo_right = max(xsearch + S(60), search_right - bw - pad)\n    self.entry_search.place(x=xsearch, y=0, width=campo_right - xsearch, height=H)\n    self.btn_karaoke.place(x=campo_right + pad, y=0,\n                           width=search_right - campo_right - pad, height=H)\n\n    bx = search_right + pad\n    self.btn_cerca.place(x=bx, y=0, width=bw, height=H); bx += bw + pad\n    self.btn_download.place(x=bx, y=0, width=bw, height=H); bx += bw + pad\n    self.btn_incolla.place(x=bx, y=0, width=bw, height=H); bx += bw + pad\n    self.btn_devoc.place(x=bx, y=0, width=bw, height=H)\n\n# ---------------- scroll rotellina ----------------'

